function buildDeltas(before: Snapshot, after: Snapshot): ITickDeltas {
  const key_seen = multisetDiff(before.key_seen, after.key_seen);
  const raw_doc = multisetDiff(before.raw_doc, after.raw_doc);
  return {
    rels: [
      { rel: "key_seen", add: key_seen.add, del: key_seen.del },
      { rel: "raw_doc", add: raw_doc.add, del: raw_doc.del },
    ],
    carryPending: false,
  };
}

